package main

import "fmt"

type Event struct {
	Seq           int
	ID, Kind, Key string
	Delta         int
}

func ReplayEvents(events []Event) (map[string]int, bool) {
	state := map[string]int{}
	seen := map[string]Event{}
	expected := 1
	maxInt := int(^uint(0) >> 1)
	minInt := -maxInt - 1
	for i, event := range events {
		fmt.Printf("Event %d: %+v\n", i, event)
		if event.ID == "" || event.Key == "" {
			fmt.Println("Invalid event ID or Key")
			return nil, false
		}
		if event.Seq != expected {
			fmt.Printf("Sequence mismatch: expected %d, got %d\n", expected, event.Seq)
			return nil, false
		}
		expected++
		// Check for duplicate event IDs with matching payloads (idempotent)
		if prevEvent, ok := seen[event.ID]; ok {
			fmt.Printf("Duplicate event found: %s\n", event.ID)
			if prevEvent != event {
				fmt.Println("Event payloads don't match")
				return nil, false
			}
			fmt.Println("Duplicate event, skipping")
			continue
		}
		seen[event.ID] = event
		fmt.Printf("Processing event: %+v\n", event)
		switch event.Kind {
		case "Add":
			current := state[event.Key]
			if event.Delta > 0 && current > maxInt-event.Delta || event.Delta < 0 && current < minInt-event.Delta {
				return nil, false
			}
			state[event.Key] = current + event.Delta
			fmt.Printf("Added %d to %s, new value: %d\n", event.Delta, event.Key, state[event.Key])
		case "Delete":
			if event.Delta != 0 {
				return nil, false
			}
			delete(state, event.Key)
			fmt.Printf("Deleted %s\n", event.Key)
		default:
			return nil, false
		}
		fmt.Printf("State after event: %+v\n", state)
	}
	return state, true
}

func main() {
	events := []Event{{1, "a", "Add", "x", 3}, {2, "b", "Add", "x", -1}, {2, "b", "Add", "x", -1}, {3, "c", "Delete", "x", 0}, {4, "d", "Add", "y", 5}}
	result, ok := ReplayEvents(events)
	fmt.Printf("Result: %+v, ok: %v\n", result, ok)
}
